<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
  <script src="https://unpkg.com/lucide@latest/dist/umd/lucide.min.js"></script>
  <script>
    tailwind.config = {
      theme: {
        extend: {
          colors: {
            brand: {
              black: '#000000',
              purple: '#7638FA',
              orange: '#FF7A00',
              'purple-light': '#A06CFF',
              'orange-light': '#FFA347',
              'magenta': '#E040FB',
            }
          },
          fontFamily: {
            sans: ['Inter', 'system-ui', 'sans-serif'],
          }
        }
      }
    }
  </script>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body { font-family: 'Inter', system-ui, sans-serif; color: #1a1a1a; background: #fff; overflow-x: hidden; }

    /* Gradient utilities */
    .gradient-hero {
      background: linear-gradient(135deg, #7638FA 0%, #E040FB 40%, #FF7A00 100%);
    }
    .gradient-text {
      background: linear-gradient(135deg, #7638FA, #E040FB, #FF7A00);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .gradient-border {
      position: relative;
    }
    .gradient-border::before {
      content: '';
      position: absolute;
      inset: 0;
      border-radius: inherit;
      padding: 2px;
      background: linear-gradient(135deg, #7638FA, #E040FB, #FF7A00);
      -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
      -webkit-mask-composite: xor;
      mask-composite: exclude;
    }

    /* Hamburger menu */
    .mobile-nav {
      transform: translateX(100%);
      transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
    }
    .mobile-nav.open {
      transform: translateX(0);
    }

    /* News carousel */
    .news-track {
      display: flex;
      gap: 1.5rem;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      padding-bottom: 1rem;
    }
    .news-track::-webkit-scrollbar { display: none; }
    .news-card {
      flex: 0 0 320px;
      scroll-snap-align: start;
    }
    @media (min-width: 768px) {
      .news-card { flex: 0 0 360px; }
    }

    /* Animations */
    @keyframes fadeInUp {
      from { opacity: 0; transform: translateY(30px); }
      to { opacity: 1; transform: translateY(0); }
    }
    @keyframes float {
      0%, 100% { transform: translateY(0); }
      50% { transform: translateY(-12px); }
    }
    @keyframes shimmer {
      0% { background-position: -200% center; }
      100% { background-position: 200% center; }
    }
    .animate-fade-in-up {
      animation: fadeInUp 0.7s ease-out forwards;
      opacity: 0;
    }
    .animate-float { animation: float 6s ease-in-out infinite; }
    .animate-shimmer {
      background-size: 200% auto;
      animation: shimmer 3s linear infinite;
    }

    /* Stagger children */
    .stagger > *:nth-child(1) { animation-delay: 0.05s; }
    .stagger > *:nth-child(2) { animation-delay: 0.15s; }
    .stagger > *:nth-child(3) { animation-delay: 0.25s; }
    .stagger > *:nth-child(4) { animation-delay: 0.35s; }

    /* Button hover */
    .btn-primary {
      transition: transform 0.15s ease, box-shadow 0.2s ease;
    }
    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 30px rgba(118, 56, 250, 0.35);
    }
    .btn-primary:active {
      transform: scale(0.97);
    }

    /* Section reveal on scroll */
    .reveal {
      opacity: 0;
      transform: translateY(40px);
      transition: opacity 0.7s ease-out, transform 0.7s ease-out;
    }
    .reveal.visible {
      opacity: 1;
      transform: translateY(0);
    }

    /* Tag pill */
    .tag-pill {
      font-size: 0.65rem;
      letter-spacing: 0.05em;
      padding: 3px 10px;
      border-radius: 9999px;
      font-weight: 600;
      text-transform: uppercase;
    }

    /* Safety section soft bg */
    .safety-bg {
      background: linear-gradient(180deg, #F5F0FF 0%, #EDE7F6 100%);
    }

    /* Creators section dynamic bg */
    .creators-bg {
      background: linear-gradient(135deg, #1a0033 0%, #2d0066 50%, #7638FA 100%);
    }

    /* Footer link hover */
    .footer-link {
      transition: color 0.15s ease;
    }
    .footer-link:hover {
      color: #A06CFF;
    }

    /* Carousel scroll button */
    .carousel-btn {
      transition: opacity 0.2s ease, transform 0.15s ease;
    }
    .carousel-btn:hover {
      transform: scale(1.1);
    }
    .carousel-btn:active {
      transform: scale(0.95);
    }

    /* Overlay backdrop */
    .overlay-backdrop {
      background: rgba(0,0,0,0.5);
      backdrop-filter: blur(4px);
    }

    /* Decorative blob */
    .blob {
      border-radius: 50%;
      filter: blur(80px);
      opacity: 0.4;
      position: absolute;
      pointer-events: none;
    }
  </style>
</head>
<body>

  <!-- ============ HEADER ============ -->
  <header class="sticky top-0 z-50 bg-white/90 backdrop-blur-md border-b border-gray-100">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
      <div class="flex items-center justify-between h-16">
        <!-- Logo -->
        <a href="#" class="flex items-center gap-2">
          <div class="w-8 h-8 rounded-lg gradient-hero flex items-center justify-center">
            <i data-lucide="aperture" class="w-5 h-5 text-white"></i>
          </div>
          <span class="text-xl font-extrabold tracking-tight">SnapFrame</span>
        </a>

        <!-- Desktop nav (hidden on mobile) -->
        <nav class="hidden md:flex items-center gap-8">
          <a href="#features" class="text-sm font-medium text-gray-600 hover:text-brand-purple transition-colors">Features</a>
          <a href="#safety" class="text-sm font-medium text-gray-600 hover:text-brand-purple transition-colors">Safety</a>
          <a href="#creators" class="text-sm font-medium text-gray-600 hover:text-brand-purple transition-colors">Creators</a>
          <a href="#news" class="text-sm font-medium text-gray-600 hover:text-brand-purple transition-colors">News</a>
          <a href="#" class="inline-flex items-center justify-center px-5 py-2 text-sm font-semibold text-white bg-brand-black rounded-full hover:bg-gray-800 transition-colors">
            Log in
          </a>
        </nav>

        <!-- Hamburger (mobile only) -->
        <button id="menu-toggle" class="md:hidden p-2 -mr-2 rounded-lg hover:bg-gray-100 transition-colors" aria-label="Open navigation menu">
          <i data-lucide="menu" class="w-6 h-6"></i>
        </button>
      </div>
    </div>
  </header>

  <!-- ============ MOBILE NAV OVERLAY ============ -->
  <div id="mobile-nav" class="mobile-nav fixed inset-0 z-[60] bg-white flex flex-col md:hidden" role="dialog" aria-label="Navigation menu">
    <div class="flex items-center justify-between h-16 px-4 border-b border-gray-100">
      <a href="#" class="flex items-center gap-2">
        <div class="w-8 h-8 rounded-lg gradient-hero flex items-center justify-center">
          <i data-lucide="aperture" class="w-5 h-5 text-white"></i>
        </div>
        <span class="text-xl font-extrabold tracking-tight">SnapFrame</span>
      </a>
      <button id="menu-close" class="p-2 -mr-2 rounded-lg hover:bg-gray-100 transition-colors" aria-label="Close navigation menu">
        <i data-lucide="x" class="w-6 h-6"></i>
      </button>
    </div>
    <nav class="flex flex-col gap-1 p-6 flex-1">
      <a href="#features" class="mobile-nav-link text-lg font-semibold py-3 px-4 rounded-xl hover:bg-gray-50 transition-colors">Features</a>
      <a href="#safety" class="mobile-nav-link text-lg font-semibold py-3 px-4 rounded-xl hover:bg-gray-50 transition-colors">Safety</a>
      <a href="#creators" class="mobile-nav-link text-lg font-semibold py-3 px-4 rounded-xl hover:bg-gray-50 transition-colors">Creators</a>
      <a href="#news" class="mobile-nav-link text-lg font-semibold py-3 px-4 rounded-xl hover:bg-gray-50 transition-colors">News</a>
      <div class="mt-auto">
        <a href="#" class="inline-flex items-center justify-center w-full px-6 py-3 text-base font-semibold text-white bg-brand-black rounded-full hover:bg-gray-800 transition-colors">
          Log in
        </a>
      </div>
    </nav>
  </div>

  <main>

    <!-- ============ HERO ============ -->
    <section class="relative overflow-hidden gradient-hero min-h-[90vh] flex items-center">
      <!-- Decorative blobs -->
      <div class="blob w-96 h-96 bg-white/20 -top-24 -left-24 animate-float"></div>
      <div class="blob w-72 h-72 bg-brand-orange/30 bottom-12 right-12" style="animation: float 8s ease-in-out infinite 1s;"></div>
      <div class="blob w-48 h-48 bg-brand-magenta/20 top-1/3 right-1/4" style="animation: float 7s ease-in-out infinite 2s;"></div>

      <div class="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-24 md:py-32">
        <div class="max-w-3xl">
          <h1 class="text-4xl sm:text-5xl md:text-6xl lg:text-7xl font-black text-white leading-[1.05] tracking-tight animate-fade-in-up">
            SnapFrame brings you closer to the people and things you love
          </h1>
          <p class="mt-6 text-lg sm:text-xl text-white/80 max-w-xl animate-fade-in-up" style="animation-delay:0.2s;">
            Capture, create, and share what you love with the people who matter most.
          </p>
          <div class="mt-10 animate-fade-in-up" style="animation-delay:0.4s;">
            <a href="#" class="btn-primary inline-flex items-center gap-2 px-8 py-4 bg-white text-brand-purple font-bold rounded-full text-lg shadow-lg">
              Try it now
              <i data-lucide="arrow-right" class="w-5 h-5"></i>
            </a>
          </div>
        </div>
      </div>

      <!-- Hero illustration elements -->
      <div class="hidden lg:block absolute right-8 top-1/2 -translate-y-1/2">
        <div class="relative">
          <div class="w-72 h-[500px] rounded-3xl bg-white/10 backdrop-blur-sm border border-white/20 p-4 animate-float" style="animation-delay:0.5s;">
            <div class="w-full h-full rounded-2xl bg-white/10 flex flex-col items-center justify-center gap-4">
              <div class="w-20 h-20 rounded-full bg-white/20 flex items-center justify-center">
                <i data-lucide="camera" class="w-10 h-10 text-white"></i>
              </div>
              <div class="flex gap-2">
                <div class="w-8 h-8 rounded-full bg-brand-orange/60"></div>
                <div class="w-8 h-8 rounded-full bg-brand-magenta/60"></div>
                <div class="w-8 h-8 rounded-full bg-white/30"></div>
              </div>
            </div>
          </div>
          <!-- Floating mini card -->
