            <div class="h-2 w-1/2 rounded bg-white/20"></div>
          </div>
          <!-- Heart icon floating -->
          <div class="absolute -right-6 bottom-24 w-14 h-14 rounded-full bg-white/20 backdrop-blur-sm border border-white/20 flex items-center justify-center animate-float" style="animation: float 4s ease-in-out infinite 0.8s;">
            <i data-lucide="heart" class="w-7 h-7 text-white"></i>
          </div>
        </div>
      </div>
    </section>

    <!-- ============ FEATURES ============ -->
    <section id="features" class="relative py-24 md:py-32 bg-white overflow-hidden reveal">
